  function optOk(o) { const p = P(); if (o.h && p.hours < o.h) return 'Il vous faut ' + o.h + ' h.'; if (o.cost && !mCan(o.cost)) return 'Plus assez d’investissement disponible cette année.'; if (o.need && !cab(o.need)) return 'Vous n’avez pas de ' + (typeof HQ !== 'undefined' ? HQ.POSTS[o.need].l.toLowerCase() : 'collaborateur') + '.'; if (o.d && !adjOf(o.d)) return 'Pas d’adjoint·e sur cette délégation.'; return true; }
