  const TEXTS = [['Projet de loi de finances : tranche d’impôt supplémentaire sur les hauts revenus', { eco: -40 }, 'fiscalite'], ['Proposition de loi sur l’aide à mourir', { soc: -45 }, 'societe'], ['Projet de loi immigration et intégration', { souv: 45 }, 'immigration'], ['Report de l’âge légal de départ à 65 ans', { eco: 40 }, 'economie'], ['Loi d’urgence agricole : moratoire sur les normes environnementales', { ecol: 40 }, 'agriculture'], ['Loi de programmation de la sécurité intérieure', { aut: 45 }, 'securite'], ['Instauration du référendum d’initiative citoyenne', { inst: 45 }, 'institutions'], ['Loi climat : interdiction des chaudières fioul en 2030', { ecol: -45 }, 'ecologie'], ['Proposition de loi sur la régulation de l’installation des médecins', { eco: -30 }, 'sante'], ['Projet de loi logement : encadrement des locations touristiques', { eco: -30 }, 'logement'], ['Projet de loi de simplification pour les entreprises', { eco: 35 }, 'economie'], ['Proposition de loi sur l’uniforme à l’école', { aut: 30, soc: 25 }, 'education']];
  function newText() { const o = of(); const t = pick(TEXTS.filter(x => !o.texte || x[0] !== o.texte.l)); const p = P(); let line = null; if (p.party !== 'NEW') { const pa = D.PARTIES[p.party].ax; let d = 0; for (const k in t[1]) d += Math.sign(t[1][k]) * Math.sign(pa[E.AXI[k]]); line = d > 0 ? 'pour' : 'contre'; } o.texte = { l: t[0], v: t[1], th: t[2], stage: 0, line, amdt: 0, spoke: false, vote: null }; }
